package calc

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"testing"
)

func huntDErr(err error) any {
	if err == nil {
		return nil
	}
	return err.Error()
}

func huntDRecord(name string, i int, input any, call func() any) {
	rec := map[string]any{"test": name, "i": i, "input": input}
	func() {
		defer func() {
			if r := recover(); r != nil {
				rec["panic"] = fmt.Sprint(r)
			}
		}()
		rec["output"] = call()
	}()
	line, err := json.Marshal(rec)
	if err != nil {
		line, _ = json.Marshal(map[string]any{"test": name, "i": i, "input": fmt.Sprintf("%#v", input), "panic": "unmarshalable: " + err.Error()})
	}
	out := os.Getenv("HUNT_DIFF_OUT")
	if out == "" {
		return
	}
	f, ferr := os.OpenFile(out, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if ferr != nil {
		panic(ferr)
	}
	defer f.Close()
	_, _ = f.Write(append(line, '\n'))
}

func huntDInts(seed int64) []int {
	r := rand.New(rand.NewSource(seed))
	out := []int{0, 1, -1, 7, -7, 1 << 20}
	for i := 0; i < 200; i++ {
		out = append(out, r.Intn(2000)-1000)
	}
	return out
}

// Recorded through the unchanged caller Total, not the changed Scale.
func TestHuntD_TotalViaCaller(t *testing.T) {
	for i, v := range huntDInts(1) {
		in := []int{v, 3}
		huntDRecord("TestHuntD_TotalViaCaller", i, in, func() any { return Total(in) })
	}
}

func TestHuntD_Ratio(t *testing.T) {
	r := rand.New(rand.NewSource(2))
	for i := 0; i < 200; i++ {
		in := []int{r.Intn(100), r.Intn(5)}
		huntDRecord("TestHuntD_Ratio", i, in, func() any { return Ratio(in[0], in[1]) })
	}
}

func TestHuntD_Label(t *testing.T) {
	for i, v := range huntDInts(3) {
		huntDRecord("TestHuntD_Label", i, v, func() any { return Label(v) })
	}
}

func TestHuntD_Bonus(t *testing.T) {
	for i, v := range huntDInts(4) {
		huntDRecord("TestHuntD_Bonus", i, v, func() any { return Bonus(v) })
	}
}
